497	    function postImpl(posted_request_num, query)
498	    {
499	        const user = document.getElementById('user').value;
500	        const password = document.getElementById('password').value;
501	
502	        const server_address = document.getElementById('url').value;
503	
504	        let url = server_address +
505	            (server_address.indexOf('?') >= 0 ? '&' : '?') +
506	            /// Ask server to allow cross-domain requests.
507	            'add_http_cors_header=1' +
508	            '&default_format=JSONCompact' +
509	            /// Safety settings to prevent results that browser cannot display.
510	            '&max_result_rows=1000&max_result_bytes=10000000&result_overflow_mode=break';
511	
512	        /// When the page is opened from a file, we cannot send custom HTTP headers,
513	        /// so we pass the credentials in the URL parameters instead.
514	        const use_url_credentials = location.protocol == 'file:';
515	        if (use_url_credentials) {
516	            url += '&user=' + encodeURIComponent(user) +
517	                '&password=' + encodeURIComponent(password);
518	        }
519	
520	        const xhr = new XMLHttpRequest;
521	
522	        xhr.open('POST', url, true);
523	
524	        /// Send the credentials in the "Authorization" header to avoid exposing them in URLs,
525	        /// which can be logged by proxies or saved in the browser history.
526	        if (!use_url_credentials) {
527	            xhr.setRequestHeader('Authorization', 'Basic ' + window.btoa(user + ':' + password));
528	        }
529	
530	        xhr.onreadystatechange = function()
531	        {
532	            if (posted_request_num != request_num) {
533	                return;
534	            } else if (this.readyState === XMLHttpRequest.DONE) {
535	                renderResponse(this.status, this.response);
536	
537	                /// The query is saved in browser history (in state JSON object)
538	                /// as well as in URL fragment identifier.
539	                if (query != previous_query) {
540	                    const state = {
541	                        query: query,
542	                        status: this.status,
543	                        response: this.response.length > 100000 ? null : this.response  /// Lower than the browser's limit.
544	                    };
545	                    const title = "ClickHouse Query: " + query;
546	
547	                    let history_url = window.location.pathname + '?user=' + encodeURIComponent(user);
548	                    if (server_address != location.origin) {
549	                        /// Save server's address in URL if it's not identical to the address of the play UI.
550	                        history_url += '&url=' + encodeURIComponent(server_address);
551	                    }
552	                    history_url += '#' + window.btoa(query);
553	
554	                    if (previous_query == '') {
555	                        history.replaceState(state, title, history_url);
556	                    } else {
557	                        history.pushState(state, title, history_url);
558	                    }
559	                    document.title = title;
560	                    previous_query = query;
561	                }
562	            } else {
563	                //console.log(this);
564	            }
565	        }
566	
567	        document.getElementById('check-mark').style.display = 'none';
568	        document.getElementById('hourglass').style.display = 'inline-block';
569	
570	        xhr.send(query);
571	    }
