573	    function renderResponse(status, response) {
574	        document.getElementById('hourglass').style.display = 'none';
575	
576	        if (status === 200) {
577	            let json;
578	            try { json = JSON.parse(response); } catch (e) {}
579	
580	            if (json !== undefined && json.statistics !== undefined) {
581	                renderResult(json);
582	            } else if (Array.isArray(json) && json.length == 2 &&
583	                Array.isArray(json[0]) && Array.isArray(json[1]) && json[0].length > 1 && json[0].length == json[1].length) {
584	                /// If user requested FORMAT JSONCompactColumns, we will render it as a chart.
585	                renderChart(json);
586	            } else {
587	                renderUnparsedResult(response);
588	            }
589	            document.getElementById('check-mark').style.display = 'inline';
590	        } else {
591	            /// TODO: Proper rendering of network errors.
592	            renderError(response);
593	        }
594	    }
