656	    function formatReadable(number = 0, decimals = 2, units = []) {
657	        const k = 1000;
658	        const i = number ? Math.floor(Math.log(number) / Math.log(k)) : 0;
659	        const unit = units[i];
660	        const dm = unit ? decimals : 0;
661	        return Number(number / Math.pow(k, i)).toFixed(dm) + unit;
662	    }
