664	    function formatReadableBytes(bytes) {
665	        const units = [' B', ' KB', ' MB', ' GB', ' TB', ' PB', ' EB', ' ZB', ' YB'];
666	
667	        return formatReadable(bytes, 2, units);
668	    }
669	
670	    function formatReadableRows(rows) {
671	        const units = ['', ' thousand', ' million', ' billion', ' trillion', ' quadrillion'];
672	
673	        return formatReadable(rows, 2, units);
674	    }
