696	    function renderCell(cell, col_idx, settings)
697	    {
698	        let td = document.createElement('td');
699	
700	        let is_null = (cell === null);
701	        let is_link = false;
702	
703	        /// Test: SELECT number, toString(number) AS str, number % 2 ? number : NULL AS nullable, range(number) AS arr, CAST((['hello', 'world'], [number, number % 2]) AS Map(String, UInt64)) AS map FROM numbers(10)
704	        let text;
705	        if (is_null) {
706	            text = 'ᴺᵁᴸᴸ';
707	        } else if (typeof(cell) === 'object') {
708	            text = JSON.stringify(cell);
709	        } else {
710	            text = cell;
711	
712	            /// If it looks like URL, create a link. This is for convenience.
713	            if (typeof(cell) == 'string' && cell.match(/^https?:\/\/\S+$/)) {
714	                is_link = true;
715	            }
716	        }
717	
718	        let node = document.createTextNode(text);
719	        if (is_link) {
720	            let link = document.createElement('a');
721	            link.appendChild(node);
722	            link.href = text;
723	            link.setAttribute('target', '_blank');
724	            node = link;
725	        }
726	
727	        if (settings.is_transposed) {
728	            td.className = 'left transposed';
729	        } else {
730	            td.className = settings.column_is_number[col_idx] ? 'right' : 'left';
731	        }
732	        if (is_null) {
733	            td.className += ' null';
734	        }
735	
736	        /// If it's a number, render bar in background.
737	        if (!settings.is_transposed && settings.column_need_render_bars[col_idx] && text > 0) {
738	            const ratio = 100 * text / settings.column_maximums[col_idx];
739	
740	            let div = document.createElement('div');
741	
742	            div.style.width = '100%';
743	            div.style.background = `linear-gradient(to right,
744	                var(--bar-color) 0%, var(--bar-color) ${ratio}%,
745	                transparent ${ratio}%, transparent 100%)`;
746	
747	            div.appendChild(node);
748	            node = div;
749	        }
750	
751	        td.appendChild(node);
752	        return td;
753	    }
